<script setup lang="ts">
import AppLayout from '@/layouts/AppLayout.vue'; import {Head,router,useForm} from '@inertiajs/vue3'; import {ref} from 'vue';
const props=defineProps<{assignments:any[];rooms:any[];selected_room:any;messages:any[];can_manage:boolean}>();
const roomForm=useForm({teaching_assignment_id:props.assignments[0]?.id??'',name:''}); const messageForm=useForm({body:''}); const showRoom=ref(false);
const send=()=>{if(!props.selected_room)return;messageForm.post(`/komunikasi/chat/ruang/${props.selected_room.id}/pesan`,{preserveScroll:true,onSuccess:()=>messageForm.reset()})};
const moderate=(id:number)=>{const reason=prompt('Alasan moderasi');if(reason)router.post(`/komunikasi/chat/pesan/${id}/moderasi`,{reason},{preserveScroll:true})};
</script>
<template><Head title="Chat Kelas"/><AppLayout><main class="view space-y-6"><section class="hero-card"><div><p class="eyebrow">Komunikasi kelas</p><h1>Chat kelas-mapel</h1><p>Ruang diskusi terisolasi sesuai penugasan mengajar dan enrollment siswa.</p></div></section><div class="chat-layout"><aside class="panel room-list"><button v-if="can_manage" class="primary-button" @click="showRoom=true">+ Buat ruang</button><button v-for="r in rooms" :key="r.id" :class="{active:selected_room?.id===r.id}" @click="router.get('/komunikasi/chat',{room_id:r.id})">{{ r.name }}</button><p v-if="!rooms.length">Belum ada ruang.</p></aside><section class="panel chat-panel"><template v-if="selected_room"><h2>{{ selected_room.name }}</h2><div class="messages"><article v-for="m in messages" :key="m.id"><strong>{{ m.user?.name }}</strong><p>{{ m.body }}</p><small>{{ new Date(m.created_at).toLocaleString('id-ID') }}</small><button v-if="can_manage&&!m.moderated_at" @click="moderate(m.id)">Moderasi</button></article></div><form class="send-box" @submit.prevent="send"><textarea v-model="messageForm.body" required maxlength="3000" placeholder="Tulis pesan"></textarea><button class="primary-button">Kirim</button></form></template><div v-else class="empty-state">Pilih atau buat ruang chat.</div></section></div><div v-if="showRoom" class="modal-backdrop" @click.self="showRoom=false"><form class="modal-card" @submit.prevent="roomForm.post('/komunikasi/chat/ruang',{onSuccess:()=>showRoom=false})"><h2>Buat ruang chat</h2><label>Penugasan<select v-model="roomForm.teaching_assignment_id"><option v-for="a in assignments" :key="a.id" :value="a.id">{{ a.subject?.name }} · {{ a.class_group?.name }}</option></select></label><label>Nama<input v-model="roomForm.name" required></label><button class="primary-button">Buat ruang</button></form></div></main></AppLayout></template>
<style scoped>.chat-layout{display:grid;grid-template-columns:250px 1fr;gap:1rem}.room-list{display:grid;align-content:start;gap:.5rem;padding:1rem}.room-list>button:not(.primary-button){padding:.7rem;text-align:left;border-radius:.6rem}.room-list .active{background:#eef2ff;color:#4338ca}.chat-panel{padding:1rem}.messages{height:55vh;overflow:auto;display:grid;align-content:start;gap:.75rem;margin:1rem 0}.messages article{position:relative;padding:.8rem;border-radius:.8rem;background:#f8fafc}.messages p{margin:.2rem 0}.messages small{color:#94a3b8}.messages button{position:absolute;right:.6rem;top:.6rem;color:#dc2626;font-size:.7rem}.send-box{display:flex;gap:.75rem}.send-box textarea{flex:1;border:1px solid #cbd5e1;border-radius:.7rem;padding:.7rem}.modal-backdrop{position:fixed;inset:0;display:grid;place-items:center;background:#0f172a88;z-index:80}.modal-card{display:grid;gap:1rem;width:min(500px,90vw);padding:1.25rem;background:white;border-radius:1rem}.modal-card label{display:grid;gap:.4rem}.modal-card input,.modal-card select{border:1px solid #cbd5e1;border-radius:.6rem;padding:.65rem}@media(max-width:760px){.chat-layout{grid-template-columns:1fr}.messages{height:45vh}}</style>
